const item = $input.item;
const j = item.json;

if (!item.binary?.data) {
  throw new Error('Arquivo binário ausente em binary.data.');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

if (!buffer || buffer.length === 0) {
  throw new Error('O arquivo binário está vazio.');
}

// SHA-256 em JavaScript puro, sem require('crypto').
function sha256(asBytes) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];

  const rotr = (x,n) => (x >>> n) | (x << (32-n));
  const bytes = Array.from(asBytes);
  const bitLen = bytes.length * 8;

  bytes.push(0x80);
  while ((bytes.length % 64) !== 56) bytes.push(0);

  const high = Math.floor(bitLen / 0x100000000);
  const low = bitLen >>> 0;

  for (let i=3; i>=0; i--) bytes.push((high >>> (i*8)) & 255);
  for (let i=3; i>=0; i--) bytes.push((low >>> (i*8)) & 255);

  let H = [
    0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
    0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
  ];

  for (let offset=0; offset<bytes.length; offset+=64) {
    const w = new Array(64);

    for (let i=0; i<16; i++) {
      const p=offset+i*4;
      w[i]=((bytes[p]<<24)|(bytes[p+1]<<16)|(bytes[p+2]<<8)|bytes[p+3])>>>0;
    }

    for (let i=16; i<64; i++) {
      const x=w[i-15], y=w[i-2];
      const s0=rotr(x,7)^rotr(x,18)^(x>>>3);
      const s1=rotr(y,17)^rotr(y,19)^(y>>>10);
      w[i]=(w[i-16]+s0+w[i-7]+s1)>>>0;
    }

    let [a,b,c,d,e,f,g,h]=H;

    for (let i=0; i<64; i++) {
      const S1=rotr(e,6)^rotr(e,11)^rotr(e,25);
      const ch=(e&f)^(~e&g);
      const t1=(h+S1+ch+K[i]+w[i])>>>0;
      const S0=rotr(a,2)^rotr(a,13)^rotr(a,22);
      const maj=(a&b)^(a&c)^(b&c);
      const t2=(S0+maj)>>>0;

      h=g; g=f; f=e; e=(d+t1)>>>0;
      d=c; c=b; b=a; a=(t1+t2)>>>0;
    }

    H=[
      (H[0]+a)>>>0,(H[1]+b)>>>0,(H[2]+c)>>>0,(H[3]+d)>>>0,
      (H[4]+e)>>>0,(H[5]+f)>>>0,(H[6]+g)>>>0,(H[7]+h)>>>0
    ];
  }

  return H.map(v=>v.toString(16).padStart(8,'0')).join('');
}

const sha = sha256(buffer);

const fileName =
  item.binary.data.fileName ||
  j.original_filename ||
  'featured-image';

const mimeType =
  item.binary.data.mimeType ||
  j.mime_type ||
  'application/octet-stream';

let width = null;
let height = null;

// Dimensões JPEG
if (mimeType === 'image/jpeg' || /\.jpe?g$/i.test(fileName)) {
  let p = 2;

  while (p < buffer.length) {
    if (buffer[p] !== 0xFF) {
      p++;
      continue;
    }

    const marker = buffer[p + 1];
    if (marker === 0xD8 || marker === 0xD9) {
      p += 2;
      continue;
    }

    if (p + 3 >= buffer.length) break;

    const len = buffer.readUInt16BE(p + 2);
    if (len < 2 || p + 2 + len > buffer.length) break;

    if ([0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF].includes(marker)) {
      height = buffer.readUInt16BE(p + 5);
      width = buffer.readUInt16BE(p + 7);
      break;
    }

    p += 2 + len;
  }
}

// Dimensões PNG
if (
  mimeType === 'image/png' ||
  /\.png$/i.test(fileName)
) {
  if (
    buffer.length >= 24 &&
    buffer[0] === 0x89 &&
    buffer.toString('ascii',1,4) === 'PNG'
  ) {
    width = buffer.readUInt32BE(16);
    height = buffer.readUInt32BE(20);
  }
}

return {
  json: {
    ...j,
    sha256: sha,
    original_filename: fileName,
    mime_type: mimeType,
    bytes: buffer.length,
    width,
    height,
  },
  binary: item.binary,
};

const item = $input.first();
const origem = $('Start Storage').first();

// A SP retorna os dados como array dentro do JSON.
const dados = item.json;
const reserva = Array.isArray(dados)
  ? dados[0]
  : Array.isArray(dados?.[0])
    ? dados[0][0]
    : dados;

if (!reserva || typeof reserva !== 'object') {
  throw new Error(
    'Não foi possível localizar o objeto da reserva na saída da SP.'
  );
}

const reservaOk =
  reserva.reserva_ok === 1 ||
  reserva.reserva_ok === '1' ||
  reserva.reserva_ok === true;

if (!reservaOk) {
  throw new Error(
    `Reserva não autorizada: ${reserva.motivo || 'motivo não informado'}`
  );
}

if (!origem.binary?.data) {
  throw new Error(
    'Arquivo binário original não encontrado em Start Storage.'
  );
}

return [
  {
    json: {
      ...reserva,
      'ind-api-folder': origem.json['ind-api-folder'],
      storage_folder: origem.json['ind-api-folder'],
    },
    binary: origem.binary,
  },
];

const apiKey = String($json.dsc_api_key ?? '').trim();
const apiSecret = String($json.dsc_api_secret ?? '').trim();
const folder = String($json.storage_folder ?? '')
  .trim()
  .replace(/^\/+|\/+$/g, '');

const baseUrl = String($json.public_base_url ?? '').trim();
const cloudMatch = baseUrl.match(
  /^https:\/\/res\.cloudinary\.com\/([^/?#]+)(?:\/|$)/
);

if (!apiKey || !apiSecret) {
  throw new Error('Credenciais Cloudinary ausentes.');
}

if (!cloudMatch) {
  throw new Error('Cloud name não identificado em public_base_url.');
}

if (!folder || !/^[a-f0-9]{64}$/i.test(String($json.sha256 ?? ''))) {
  throw new Error('Pasta ou SHA-256 inválido.');
}

if (!$binary?.data) {
  throw new Error('Binário data ausente.');
}

return {
  json: {
    ...$json,
    storage_folder: folder,
    cloudinary_cloud: cloudMatch[1],
    cloudinary_public_id: `${folder}/${$json.sha256}`,
    AUTHORIZATION:
      `Basic ${Buffer.from(`${apiKey}:${apiSecret}`, 'utf8').toString('base64')}`,
  },
  binary: $binary,
};

// Valida a primeira linha retornada pela SP.
const dados = $input.first().json;

const finalizacao = Array.isArray(dados)
  ? Array.isArray(dados[0])
    ? dados[0][0]
    : dados[0]
  : dados;

if (Number(finalizacao?.finalizacao_ok) !== 1) {
  throw new Error(
    `Finalização não confirmada: ${
      finalizacao?.motivo || 'retorno inválido da SP'
    }`
  );
}

// Recupera o contexto da execução corrente.
const contexto = $('SHA-256 + Metadados').itemMatching(0).json;

// R2 e B2 compartilham driver; a seleção é por provider.
const nodesUpload = {
  cloudinary: 'Upload Cloudinary - Proxy',
  cloudflare_r2: 'Upload S3R2 - Proxy',
  backblaze_b2: 'Upload S3B2 - Proxy',
};

const nomeUpload = nodesUpload[contexto.provider];

if (!nomeUpload) {
  throw new Error(
    `Provider não suportado: ${contexto.provider}`
  );
}

if (
  Number(finalizacao.storage_id) !==
  Number(contexto.storage_id)
) {
  throw new Error(
    'Finalização não corresponde ao storage da execução.'
  );
}

// Recupera a resposta do upload.
const resposta = $(nomeUpload).itemMatching(0).json;
let upload = resposta.body ?? resposta;

// Algumas configurações HTTP retornam o body como texto.
if (typeof upload === 'string') {
  try {
    upload = JSON.parse(upload);
  } catch {
    throw new Error('Resposta do upload não contém JSON válido.');
  }
}

if (
  !upload ||
  typeof upload !== 'object' ||
  Array.isArray(upload)
) {
  throw new Error('Resposta do upload não contém um objeto de mídia.');
}

if (
  upload.provider &&
  upload.provider !== contexto.provider
) {
  throw new Error('Provider do upload não corresponde à reserva.');
}

if (
  upload.sha256 &&
  upload.sha256 !== contexto.sha256
) {
  throw new Error(
    'SHA-256 do upload não corresponde ao arquivo enviado.'
  );
}

// Valida os metadados.
const secureUrl = upload.secure_url;
const width = Number(upload.width);
const height = Number(upload.height);
const bytes = Number(upload.bytes ?? contexto.bytes);

// Não utiliza a classe URL, indisponível no sandbox desta instância.
let urlValida = false;

if (typeof secureUrl === 'string') {
  const match = secureUrl.match(
    /^https:\/\/([a-z0-9.-]+)(?::([0-9]{1,5}))?(\/[^\s\\]*)?$/i
  );

  if (match) {
    const host = match[1];
    const porta = match[2];

    const hostValido =
      host.length <= 253 &&
      host.includes('.') &&
      host.split('.').every(
        parte =>
          parte.length >= 1 &&
          parte.length <= 63 &&
          /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(parte)
      );

    urlValida =
      hostValido &&
      (
        !porta ||
        (Number(porta) >= 1 && Number(porta) <= 65535)
      );
  }
}

const widthValido = Number.isInteger(width) && width > 0;
const heightValido = Number.isInteger(height) && height > 0;
const bytesValidos = Number.isInteger(bytes) && bytes > 0;

if (
  !urlValida ||
  !widthValido ||
  !heightValido ||
  !bytesValidos
) {
  throw new Error(
    'Resposta de upload inválida: ' +
    JSON.stringify({
      provider: contexto.provider,
      storage_id: contexto.storage_id,
      nodeUpload: nomeUpload,
      urlValida,
      widthValido,
      heightValido,
      bytesValidos,
    })
  );
}

if (!/^[a-f0-9]{64}$/i.test(String(contexto.sha256 ?? ''))) {
  throw new Error('SHA-256 do contexto ausente ou inválido.');
}

// Preserva IDs reais; permite fallback para providers de objetos.
const providerObjeto = [
  'cloudflare_r2',
  'backblaze_b2',
].includes(contexto.provider);

const publicId = upload.public_id ??
  (
    providerObjeto && contexto.storage_folder
      ? `${contexto.storage_folder}/${contexto.sha256}`
      : null
  );

const assetId = upload.asset_id ??
  (providerObjeto ? upload.object_key : null);

if (!publicId || !assetId) {
  throw new Error(
    'Resposta de upload sem identificadores da mídia.'
  );
}

const mimeType = upload.mime_type ?? contexto.mime_type;

if (!['image/jpeg', 'image/png', 'image/webp'].includes(mimeType)) {
  throw new Error('MIME da mídia ausente ou não suportado.');
}

// Retorna somente os insumos de mídia para o fluxo pai.
// Não transporta credenciais, autorização ou token da reserva.
return [
  {
    json: {
      provider: contexto.provider,
      sha256: contexto.sha256,
      asset_id: assetId,
      public_id: publicId,
      secure_url: secureUrl,
      url: secureUrl,
      width,
      height,
      mime_type: mimeType,
      original_filename: String(
        contexto.original_filename ?? ''
      ).trim(),
      bytes,
      existing: upload.existing === true,
    },
  },
];

const dados = $input.first().json;

const resultado = Array.isArray(dados)
  ? Array.isArray(dados[0])
    ? dados[0][0]
    : dados[0]
  : dados;

if (Number(resultado?.finalizacao_ok) !== 1) {
  throw new Error(
    `Finalização não confirmada: ${
      resultado?.motivo || 'retorno inválido da SP'
    }`
  );
}

return [{
  json: resultado,
}];
